// themeStore.ts
export const useThemeStore = create<ThemeState>((set) => ({
  theme: "system",
  setTheme: (theme) => {
    set({ theme });
    localStorage.setItem("theme", theme);
    applyTheme(theme);
  },
}));

# 情绪适配判断：O(1) 索引查询
def is_mood_match(self, recipe, emotion):
    idx = self._id2idx.get(id(recipe))
    if idx is not None:
        return idx in self._mood_hint_index.get(emotion, ())
    return emotion in (recipe.get('mood_hint') or [])

def vividness_of(event, half_life_days=30.0):
    """遗忘曲线：清晰度 = base × 0.5^(天数/半衰期)"""
    if event.get("important"):
        return 100  # 重要记忆永不遗忘
    days = (now - anchor) / 86400.0
    return max(5, round(base * 0.5 ** (days / half_life_days)))

def _fingerprint(self):
    # 轻量状态指纹：插件元数据 + 已注册 handler 概要
    # 任何指令增删、插件启停都会改变指纹
    parts = []
    for path, md in star_map.items():
        parts.append(f'{path}|{getattr(md, "activated", True)}|...')
    for handler in star_handlers_registry:
        parts.append(f'{handler.handler_module_path}|{handler.handler_name}|...')
    return hashlib.sha1('|'.join(sorted(parts)).encode()).hexdigest()[:10]

# 关系角色豁免判定
def _is_relationship_expression_exempt(text, matched, role_vocab):
    # 命中规则必须是纯身份指派类（软规则）
    # 不得出现其他硬关键词
    # 身份触发词后 8 字符内须出现关系角色词
    for m in _IDENTITY_TRIGGER_RE.finditer(text):
        window = text[m.end(): m.end() + 8]
        for role in role_vocab:
            if role in window:
                return True
    return False

